--- /dev/null
+++ b/src/util/sanitize.js
@@ -0,0 +1,31 @@
+/**
+ * Sanitization utilities for preventing XSS attacks
+ * @namespace sanitize
+ */
+
+/**
+ * Escape HTML entities to prevent XSS when inserting text into HTML/SVG
+ * @param {string} str - The string to escape
+ * @returns {string} The escaped string safe for HTML context
+ */
+const escapeHtml = function (str) {
+    if (typeof str !== 'string') return str;
+    const htmlEntities = {
+        '&': '&amp;',
+        '<': '&lt;',
+        '>': '&gt;',
+        '"': '&quot;',
+        "'": '&#x27;',
+        '/': '&#x2F;'
+    };
+    return str.replace(/[&<>"'/]/g, char => htmlEntities[char]);
+};
+
+/**
+ * Sanitize SVG content to remove potentially dangerous elements and attributes
+ * @param {string} svgString - The SVG string to sanitize
+ * @returns {string} Sanitized SVG string safe for embedding
+ */
+const sanitizeSvg = function (svgString) {
+    if (typeof svgString !== 'string') return svgString;
+    // Remove script elements and javascript: URLs
+    return svgString
+        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
+        .replace(/\sjavascript\s*:/gi, ' data:')
+        .replace(/on\w+\s*=/gi, 'data-on=');
+};
+
+module.exports = {escapeHtml, sanitizeSvg};

